def verif_vertex_cover(G: nx.Graph, nodes: set):
    s = set(nodes)
    for (u,v) in G.edges():
        if u not in s and v not in s:
            return False
    return True

import numpy as np
import random
def generate_random_subset(G: nx.Graph):
    nodes = list(G.nodes())
    n = len(nodes)
    nb = np.random.randint(2, n)
    random.shuffle(nodes)
    return set(nodes[:nb])

